/** Private recording document: preview first, then explicit Save/Share/GIF conversion. No OCR. */
public class RecordingResultActivity extends Activity {
    private CaptureWindow pinnedWindow;private int floatingX=Integer.MIN_VALUE,floatingY=-1;private File file;private RecordingPlayer video;private int playbackPosition;private boolean playbackPlaying,large;private boolean pinned,folded,busy;private volatile boolean cancelled;private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private long duration;private int shortSide=240;private TextView progress,operationStatus;private String operationMessage="";
    @Override public void onCreate(Bundle saved){super.onCreate(saved);if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,()->{if(busy)cancelled=true;else if(large){large=false;render();}else finish();});ThemePolicy.apply(this);getWindow().setBackgroundDrawableResource(android.R.color.transparent);try{file=RecordingFiles.checked(this,saved==null?getIntent().getStringExtra("path"):saved.getString("path",getIntent().getStringExtra("path")));}catch(Exception e){finish();return;}readDuration();shortSide=Prefs.of(this).getInt("gif_resolution",240);if(saved!=null){pinned=saved.getBoolean("pinned");folded=saved.getBoolean("folded");}render();if(getIntent().getBooleanExtra("auto_gif",false)&&!isGif())convert(0,30000);}
    private void readDuration(){if(isGif())return;MediaMetadataRetriever retriever=new MediaMetadataRetriever();try{retriever.setDataSource(file.getPath());duration=Long.parseLong(retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION));}catch(Exception ignored){duration=0;}finally{try{retriever.release();}catch(Exception ignored){}}}
    private int dp(float n){return Ui.dp(this,n);}private boolean isGif(){return file.getName().endsWith(".gif");}
    private void icon(LinearLayout row,String id,String label,Runnable action){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(40),dp(40));p.leftMargin=dp(2);row.addView(Ui.tool(this,id,label,action),p);}
    private void action(LinearLayout row,String id,String name,String label,Runnable run){LinearLayout b=Ui.action(this,id,name,label,run);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(44),1);p.setMargins(dp(4),0,dp(4),0);row.addView(b,p);}
    private void stopVideo(){if(video!=null){playbackPosition=video.position();playbackPlaying=video.playing();video.release();video=null;}}
    private void render(){if(isFinishing()||isDestroyed())return;stopVideo();if(pinnedWindow!=null){pinnedWindow.remove();pinnedWindow=null;}ThemePolicy.apply(this);if(pinned&&!large)pinnedWindow=new CaptureWindow(this);FrameLayout root=pinned&&!large?pinnedWindow.frame(this::finish):new FrameLayout(this);root.setBackgroundColor(Color.TRANSPARENT);if(large){showLarge(root);return;}root.setOnClickListener(v->{if(!pinned&&!busy)finish();});LinearLayout card=Ui.card(this);Ui.pad(card,16,12,16,16);Ui.softShadow(card);card.setOnClickListener(v->{});LinearLayout heading=Ui.row(this);if(large)icon(heading,"back","返回录制结果",()->{large=false;render();});TextView title=Ui.text(this,isGif()?"GIF 预览":large?"视频预览":"录屏预览",18,Ui.INK,true);title.setContentDescription("拖动录制结果窗口");heading.addView(title,new LinearLayout.LayoutParams(0,-2,1));title.setOnTouchListener(new View.OnTouchListener(){float x,y;int oldX,oldY;public boolean onTouch(View v,MotionEvent e){if(!pinned||pinnedWindow==null)return false;switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN->{int[] at=pinnedWindow.position();x=e.getRawX();y=e.getRawY();oldX=at[0];oldY=at[1];return true;}case MotionEvent.ACTION_MOVE->{floatingX=oldX+Math.round(e.getRawX()-x);floatingY=Math.max(dp(24),Math.min(getResources().getDisplayMetrics().heightPixels-dp(60),oldY+Math.round(e.getRawY()-y)));pinnedWindow.move(floatingX,floatingY);return true;}case MotionEvent.ACTION_UP->{v.performClick();int width=getResources().getDisplayMetrics().widthPixels-dp(16);if(floatingX<-width/2||floatingX>getResources().getDisplayMetrics().widthPixels-width/2)edgeTab(floatingX<0);return true;}}return true;}});icon(heading,folded?"expand":"collapse",folded?"展开录制结果":"收起录制结果",()->{folded=!folded;render();});icon(heading,pinned?"pinned":"pin",pinned?"取消置顶录制结果":"置顶录制结果",()->{pinned=!pinned;if(!pinned)bringToFront();render();});icon(heading,"close","关闭录制结果",()->{if(!busy)finish();});card.addView(heading);
        if(busy){Ui.gap(card,20);progress=Ui.text(this,"正在转换 GIF…",15,Ui.INK,false);card.addView(progress);Ui.gap(card,20);card.addView(Ui.button(this,"取消转换",false,()->{cancelled=true;}));}
        else if(!folded){Ui.gap(card,12);int height=Math.min(dp(230),getResources().getDisplayMetrics().heightPixels/3);if(isGif()){View gif=RecordingMediaView.decode(this,file,Math.min(720,getResources().getDisplayMetrics().widthPixels));if(gif!=null){gif.setContentDescription("GIF 动态预览，点击放大");gif.setOnClickListener(v->{large=true;render();});Ui.frame(gif,Ui.BG,14);card.addView(gif,new LinearLayout.LayoutParams(-1,height));}}else{video=new RecordingPlayer(this,file,large,playbackPosition,playbackPlaying,()->{large=true;render();});card.addView(video,new LinearLayout.LayoutParams(-1,height));}

            Ui.gap(card,12);LinearLayout actions=Ui.row(this);action(actions,"save","保存","保存录制",this::save);action(actions,"share","分享","分享录制",this::share);if(!isGif())action(actions,"gif_record","转 GIF","转为 GIF",this::conversionOptions);card.addView(actions);Ui.gap(card,6);operationStatus=Ui.text(this,operationMessage.isEmpty()?"预览保存在临时空间；点保存后才写入相册。":operationMessage,11,Ui.MUTED,false);operationStatus.setContentDescription("录制操作状态");card.addView(operationStatus);}
        int width=getResources().getDisplayMetrics().widthPixels-dp(pinned&&!large?40:16);if(pinned&&!large){root.setPadding(dp(12),dp(12),dp(12),dp(12));root.addView(card,new FrameLayout.LayoutParams(-1,-2));setContentView(new FrameLayout(this));WindowManager.LayoutParams host=getWindow().getAttributes();host.width=host.height=1;host.gravity=Gravity.TOP|Gravity.LEFT;host.flags|=WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL;host.flags&=~WindowManager.LayoutParams.FLAG_DIM_BEHIND;getWindow().setAttributes(host);if(floatingX==Integer.MIN_VALUE){floatingX=dp(8);floatingY=dp(100);}pinnedWindow.showFloating(root,width+dp(24),getResources().getDisplayMetrics().heightPixels-dp(80),floatingX,floatingY);}else{FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(width,-2,Gravity.CENTER);root.addView(card,p);setContentView(root);WindowManager.LayoutParams at=getWindow().getAttributes();at.flags&=~(WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS|WindowManager.LayoutParams.FLAG_WATCH_OUTSIDE_TOUCH);at.width=-1;at.height=-1;at.gravity=Gravity.CENTER;at.x=at.y=0;getWindow().setAttributes(at);}Prefs.of(this).edit().putString("record_result_kind",isGif()?"gif":"video").putString("record_result_path",file.getPath()).putBoolean("record_result_ocr",false).apply();}
    private void bringToFront(){try{startActivity(new Intent(this,RecordingResultActivity.class).putExtra("path",file.getPath()).addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT|Intent.FLAG_ACTIVITY_SINGLE_TOP));overridePendingTransition(0,0);}catch(RuntimeException ignored){}}
    private void normalWindow(){WindowManager.LayoutParams p=getWindow().getAttributes();p.flags&=~(WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_WATCH_OUTSIDE_TOUCH|WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS);p.width=p.height=-1;p.x=p.y=0;p.gravity=Gravity.CENTER;getWindow().setAttributes(p);}
    private void showLarge(FrameLayout root){if(!pinned)normalWindow();else{pinnedWindow=new CaptureWindow(this);root=pinnedWindow.frame(()->{large=false;render();});}root.setBackgroundColor(0xED101A16);root.setContentDescription("录制大图预览暗色背景");root.setOnClickListener(v->{large=false;render();});if(isGif()){View gif=RecordingMediaView.decode(this,file,getResources().getDisplayMetrics().widthPixels);if(gif!=null){int width=getResources().getDisplayMetrics().widthPixels,height=getResources().getDisplayMetrics().heightPixels-dp(140);if(gif instanceof ImageView iv&&iv.getDrawable()!=null)height=Math.min(height,Math.round(width*iv.getDrawable().getIntrinsicHeight()/(float)Math.max(1,iv.getDrawable().getIntrinsicWidth())));FrameLayout.LayoutParams at=new FrameLayout.LayoutParams(-1,height,Gravity.CENTER);root.addView(gif,at);gif.setOnClickListener(v->{});gif.setOnTouchListener((v,e)->{if(e.getActionMasked()==MotionEvent.ACTION_UP&&gif instanceof ImageView iv&&iv.getDrawable()!=null){android.graphics.drawable.Drawable d=iv.getDrawable();float fit=Math.min(v.getWidth()/(float)Math.max(1,d.getIntrinsicWidth()),v.getHeight()/(float)Math.max(1,d.getIntrinsicHeight())),left=(v.getWidth()-d.getIntrinsicWidth()*fit)/2,top=(v.getHeight()-d.getIntrinsicHeight()*fit)/2;if(e.getX()<left||e.getX()>v.getWidth()-left||e.getY()<top||e.getY()>v.getHeight()-top){large=false;render();return true;}}return false;});}}else{video=new RecordingPlayer(this,file,true,playbackPosition,playbackPlaying,()->{});FrameLayout.LayoutParams at=new FrameLayout.LayoutParams(-1,-1);at.setMargins(dp(8),dp(48),dp(8),dp(40));root.addView(video,at);}if(pinned)pinnedWindow.show(root,true);else setContentView(root);}
    private void edgeTab(boolean left){if(video!=null)video.pause();if(pinnedWindow==null)return;int height=pinnedWindow.root().getHeight();DockMorph.dock(this,pinnedWindow.manager,(FrameLayout)pinnedWindow.root(),left,isGif()?"gif_record":"record","展开置顶录制标签",()->{int[] at=pinnedWindow.position();floatingX=at[0];floatingY=at[1];});}
    @Override public boolean dispatchTouchEvent(MotionEvent event){if(pinned){if(event.getActionMasked()==MotionEvent.ACTION_OUTSIDE){getWindow().getDecorView().animate().alpha(.45f).setDuration(280).start();return false;}if(event.getActionMasked()==MotionEvent.ACTION_DOWN)getWindow().getDecorView().animate().alpha(1).setDuration(160).start();}return super.dispatchTouchEvent(event);}
    private void report(String message){operationMessage=message;if(operationStatus!=null)operationStatus.setText(message);Feedback.show(this,message);}
    private void save(){if(busy){report("正在处理，请稍候");return;}busy=true;report(isGif()?"正在保存 GIF…":"正在保存视频…");stopVideo();worker.execute(()->{Uri uri=null;String error=null;try{uri=RecordingFiles.save(this,file);}catch(Exception e){error=e.getMessage();}Uri saved=uri;String failure=error;main.post(()->{busy=false;if(isFinishing())return;if(saved!=null){Prefs.of(this).edit().putString("last_record_saved_uri",saved.toString()).apply();report(isGif()?"GIF 已保存到相册 Pictures/Kongye":"视频已保存到相册 Movies/Kongye");}else report("保存失败："+(failure==null?"请检查剩余空间或权限":failure));render();});});}
    private void share(){if(busy)return;busy=true;stopVideo();worker.execute(()->{Uri uri=null;try{uri=ShareImageProvider.prepareMedia(this,file);}catch(Exception ignored){}Uri target=uri;main.post(()->{busy=false;if(isFinishing())return;if(target==null){report("无法准备分享文件");render();return;}Intent send=new Intent(Intent.ACTION_SEND).setType(isGif()?"image/gif":"video/mp4").putExtra(Intent.EXTRA_STREAM,target).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);send.setClipData(ClipData.newRawUri("空叶录制",target));try{startActivity(Intent.createChooser(send,"分享录制"));}catch(RuntimeException e){report("没有可分享的应用");}render();});});}
    private void conversionOptions(){if(busy)return;LinearLayout body=Ui.column(this);Ui.pad(body,20,8,20,0);body.addView(Ui.text(this,"GIF 无声音，按所选最大帧数；每次可转换最多 30 秒。",12,Ui.MUTED,false));EditText start=Ui.field(this,"起始秒");start.setContentDescription("GIF 起始秒");start.setHint("起始秒");start.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);start.setText("0");body.addView(start,new LinearLayout.LayoutParams(-1,dp(44)));Ui.gap(body,8);EditText length=Ui.field(this,"持续秒数");length.setContentDescription("GIF 持续秒数");length.setHint("持续秒数");length.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);length.setText(String.valueOf(Math.max(1,Math.min(30,duration/1000))));body.addView(length,new LinearLayout.LayoutParams(-1,dp(44)));Ui.gap(body,8);final int[] resolution={shortSide<=240?0:shortSide<=480?1:shortSide<=720?2:3};body.addView(Ui.segmented(this,new String[]{"240p","480p","720p","1080p"},resolution[0],index->{resolution[0]=index;}));AlertDialog dialog=new UiDialog(this).setTitle("转为 GIF").setView(body).setPositiveButton("转换",null).setNegativeButton("取消",null).create();dialog.setOnShowListener(d->{UiDialog.style(dialog);dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{long offset=Long.parseLong(start.getText().toString())*1000,ms=Long.parseLong(length.getText().toString())*1000;if(offset<0||offset>=duration||ms<200||ms>30000)throw new NumberFormatException();shortSide=new int[]{240,480,720,1080}[resolution[0]];dialog.dismiss();convert(offset,ms);}catch(NumberFormatException e){report("请输入视频内的起点和 1–30 秒时长");}});});dialog.show();}
    private void convert(long start,long ms){if(busy)return;busy=true;cancelled=false;stopVideo();render();File source=file;worker.execute(()->{File gif=null;String error=null;try{gif=GifConversion.convert(this,source,shortSide,start,ms,getIntent().getIntExtra("gif_fps",Prefs.of(this).getInt("gif_fps",10)),()->cancelled||isFinishing(),value->main.post(()->{if(progress!=null)progress.setText("正在转换 GIF… "+value+"%");}));}catch(Exception|OutOfMemoryError e){error=e.getMessage();}File result=gif;String failure=error;main.post(()->{busy=false;if(isFinishing())return;if(result!=null){file=result;large=false;playbackPosition=0;playbackPlaying=false;Prefs.of(this).edit().putString("last_gif_path",file.getPath()).apply();report("GIF 已生成，可保存或分享");}else report(cancelled?"已取消 GIF 转换":"GIF 未生成："+failure);render();});});}
    @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putString("path",file.getPath());b.putBoolean("pinned",pinned);b.putBoolean("folded",folded);}
    @Override public boolean dispatchKeyEvent(KeyEvent e){if(e.getKeyCode()==KeyEvent.KEYCODE_BACK&&busy){if(e.getAction()==KeyEvent.ACTION_UP)cancelled=true;return true;}return super.dispatchKeyEvent(e);}
    @Override protected void onPause(){if((getApplicationInfo().flags&android.content.pm.ApplicationInfo.FLAG_DEBUGGABLE)!=0)Prefs.of(this).edit().putLong("qa_player_pause_at",SystemClock.uptimeMillis()).apply();if(video!=null&&!pinned)video.pause();super.onPause();}
    @Override protected void onDestroy(){cancelled=true;stopVideo();if(pinnedWindow!=null){pinnedWindow.remove();pinnedWindow=null;}worker.shutdown();super.onDestroy();}
}
